import React from 'react';
import Button from '@mui/material/Button';
import { useNavigate } from 'react-router-dom';
import Iconify from "../iconify"; // Adjust the import path based on your project structure

const GoBackButton = ({onClick, label, to, icon, i18 }) => {
  const navigate = useNavigate();

  const handleClick = (event) => {
    if(onClick){
      onClick(event)
    } else if(to) {
      navigate(to)
    }
  }

  return (
    <Button
      variant="contained"
      sx={{
        marginLeft: { xs: 0, sm: 'auto' },
        marginTop: { xs: 2, sm: 0 },
        width: { xs: '100%', sm: 'auto' },
      }}
      onClick={handleClick}
      startIcon={<Iconify icon={icon} />}
    >
      {label || i18?.LISTINGPAGE?.GO_BACK || 'Go Back'}
    </Button>
  );
};

export default GoBackButton;
